class QueueCreateRequest(BaseModel):
    name: str


class MessageRequest(BaseModel):
    content: str


@app.get("/status")
def get_status():
    """Return basic service status"""
    return {"status": "ok"}


@app.post("/queues")
def create_queue(request: QueueCreateRequest):
    """Create new queue with JSON body: {"name": "queue_name"}"""
    name = request.name
    # Check if queue exists
    if load_queue(name)["messages"] is not None:
        # Queue exists, check if it has messages or is empty file
        # Actually, we should check if file exists and is valid
        pass

    # Try to load - if it has messages, queue exists
    existing = load_queue(name)
    if "messages" in existing:
        raise HTTPException(status_code=400, detail=f"Queue '{name}' already exists")

    # Create new queue with empty messages list
    save_queue(name, {"messages": []})
    return {"message": f"Queue '{name}' created"}


