    save_queue(queue_name, data)
    return {"message": f"Message added to queue '{queue_name}'"}


@app.get("/queues/{queue_name}/messages")
def receive_message(queue_name: str):
    """Receive/consume one message"""
    data = load_queue(queue_name)
    messages = data.get("messages", [])

    if len(messages) == 0:
        # Queue doesn't exist or is empty - return 204
        # But we need to check if queue exists at all
        # According to spec: "404 for non-existent queues"
        # Empty queue should return 204
        # So we need to distinguish between non-existent and empty
        # Actually, let's check: if queue file doesn't exist, 404. If file exists but empty messages, 204
        file_path = get_queue_file(queue_name)
        if not file_path.exists():
            raise HTTPException(status_code=404, detail=f"Queue '{queue_name}' not found")
        return status.HTTP_204_NO_CONTENT

    # FIFO: get first message and remove it
    message = messages.pop(0)
    save_queue(queue_name, data)
    return {"content": message}


